final class ProcOpenNativeProcessRunner implements NativeProcessRunner { public function run(NativeProcessRequest $r):NativeProcessResult{$pipes=[];$p=@proc_open([$r->executable,...$r->arguments],[0=>$r->stdin?['file',$r->stdin,'r']:['pipe','r'],1=>$r->stdout?['file',$r->stdout,'w']:['pipe','w'],2=>['pipe','w']],$pipes,null,null,['bypass_shell'=>true]);if(!is_resource($p))throw new InvalidArgumentException('Native process could not be started.');if(isset($pipes[0]))fclose($pipes[0]);$stderr=stream_get_contents($pipes[2],8192)?:'';fclose($pipes[2]);if(isset($pipes[1])){stream_get_contents($pipes[1]);fclose($pipes[1]);}return new NativeProcessResult(proc_close($p),substr(preg_replace('/[\x00-\x1F\x7F]/','',$stderr)??'',0,8192));}}
